        vel_EmbersEmitter[i].y += 5.88 * dt;
        
        const speed_EmbersEmitter = vel_EmbersEmitter[i].length();
        const limit_EmbersEmitter = 0.7 * 2.0;
        if (speed_EmbersEmitter > limit_EmbersEmitter) {
          const percent = (speed_EmbersEmitter - limit_EmbersEmitter) / speed_EmbersEmitter;
          vel_EmbersEmitter[i].multiplyScalar(Math.max(0, 1 - percent * 0.15 * dt * 20));
        }
    
        pos_EmbersEmitter[i].addScaledVector(vel_EmbersEmitter[i], dt);
        


        

        const sizeBez: PiecewiseCurve[] = [{start: 0, end: 0.3684014, p0: 0.18110657, p1: 0.6493777458853933, p2: 0.9957915115279413, p3: 0.9608776}, {start: 0.3684014, end: 1, p0: 0.9608776, p1: 0.9010201248612747, p2: 0.029164688532285335, p3: 0}];
        const scaledSz = sz_EmbersEmitter[i] * 2.0 * evalPiecewise(sizeBez, pct);

        const alpha = alphaKeys_EmbersEmitter ? evalAlpha(alphaKeys_EmbersEmitter, pct) : (1 - pct);
        if (colorKeys_EmbersEmitter) evalColor(colorKeys_EmbersEmitter, pct, _col); else { _col.r = 1; _col.g = 1; _col.b = 1; }
        const col = _col;

        T.position.set(0, 0, 0);
        T.quaternion.set(0, 0, 0, 1);
        
        // StretchedBillboard: shader handles orientation via aVelocity/aOffset
        T.scale.setScalar(scaledSz);
        off_buf_EmbersEmitter[i*3+0] = pos_EmbersEmitter[i].x;
        off_buf_EmbersEmitter[i*3+1] = pos_EmbersEmitter[i].y;
        off_buf_EmbersEmitter[i*3+2] = pos_EmbersEmitter[i].z;
        vel_buf_EmbersEmitter[i*3+0] = vel_EmbersEmitter[i].x * 0.0100;
        vel_buf_EmbersEmitter[i*3+1] = vel_EmbersEmitter[i].y * 0.0100;
        vel_buf_EmbersEmitter[i*3+2] = vel_EmbersEmitter[i].z * 0.0100;
        
