    mesh_FlamethrowerSharpBlueEmitter.frustumCulled = false;
    this.scene.add(mesh_FlamethrowerSharpBlueEmitter);
    const frm_FlamethrowerSharpBlueEmitter = new Float32Array(cnt_FlamethrowerSharpBlueEmitter);
    const opc_FlamethrowerSharpBlueEmitter = new Float32Array(cnt_FlamethrowerSharpBlueEmitter);
    const clr_FlamethrowerSharpBlueEmitter = new Float32Array(cnt_FlamethrowerSharpBlueEmitter * 3);
